def is_prime(n: int) -> bool:
    """Return True if n is a prime number, otherwise False."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


def filter_primes(numbers: list[int]) -> list[int]:
    """Return a new list containing only the prime numbers from the input list."""
    return [n for n in numbers if is_prime(n)]
```

This defines a helper `is_prime` and then `filter_primes` that returns only the primes from the input list.
